    Bug 1972857 - Make sure all cases of opening compose first open a 3pane window. r=edicharry


    We had missed handling the anchient -remote commands (Firefox removed them in bug 1080319)

    I don't think openurl ever did something useful in Thunderbird.

    Differential Revision: https://phabricator.services.mozilla.com/D256792

diff --git a/mail/components/MessengerContentHandler.sys.mjs b/mail/components/MessengerContentHandler.sys.mjs
index 933a64ae82b..c1b7aae2ce8 100644
--- a/mail/components/MessengerContentHandler.sys.mjs
+++ b/mail/components/MessengerContentHandler.sys.mjs
@@ -278,77 +278,73 @@ export class MessengerContentHandler {
       throw Components.Exception("", Cr.NS_ERROR_ABORT);
     }

-    if (remoteCommand != null) {
-      try {
-        var a = /^\s*(\w+)\(([^\)]*)\)\s*$/.exec(remoteCommand);
-        var remoteVerb = a[1].toLowerCase();
-        var remoteParams = a[2].split(",");
-
-        switch (remoteVerb) {
-          case "openurl": {
-            const xuri = cmdLine.resolveURI(remoteParams[0]);
-            openURI(xuri);
-            break;
-          }
-          case "mailto": {
-            const xuri = cmdLine.resolveURI("mailto:" + remoteParams[0]);
+    if (remoteCommand) {
+      const a = /^\s*(\w+)\(([^\)]*)\)\s*$/.exec(remoteCommand);
+      const remoteVerb = a[1].toLowerCase();
+      const remoteParams = a[2].split(",");
+
+      switch (remoteVerb) {
+        case "mailto": {
+          // -remote "mailto(foo@example.com)"
+          const xuri = cmdLine.resolveURI("mailto:" + remoteParams[0]);
+          getOrOpen3PaneWindow().then(_win => {
+            if (!MailServices.accounts.defaultAccount) {
+              return; // No account yet; can't compose.
+            }
             openURI(xuri);
-            break;
-          }
-          case "xfedocommand":
-            // xfeDoCommand(openBrowser)
-            switch (remoteParams[0].toLowerCase()) {
-              case "openinbox": {
-                getOrOpen3PaneWindow().then(win => win.focus());
-                break;
-              }
-              case "composemessage": {
-                const argstring = Cc[
-                  "@mozilla.org/supports-string;1"
-                ].createInstance(Ci.nsISupportsString);
-                remoteParams.shift();
-                argstring.data = remoteParams.join(",");
-                const args = Cc["@mozilla.org/array;1"].createInstance(
-                  Ci.nsIMutableArray
+          });
+          break;
+        }
+        case "xfedocommand":
+          switch (remoteParams[0].toLowerCase()) {
+            case "openinbox": {
+              // -remote "xfedocommand(openinbox)"
+              getOrOpen3PaneWindow().then(win => win.focus());
+              break;
+            }
+            case "composemessage": {
+              // -remote "xfedocommand(composemessage,subject='hey',to='foo@example.com',body='hey you',attachment='$(readlink -f /tmp/foo)')"
+              const argstring = Cc[
+                "@mozilla.org/supports-string;1"
+              ].createInstance(Ci.nsISupportsString);
+              remoteParams.shift();
+              argstring.data = remoteParams.join(",");
+              const args = Cc["@mozilla.org/array;1"].createInstance(
+                Ci.nsIMutableArray
+              );
+              args.appendElement(argstring);
+              args.appendElement(cmdLine);
+              getOrOpen3PaneWindow().then(win => {
+                if (!MailServices.accounts.defaultAccount) {
+                  return; // No account yet; can't compose.
+                }
+                Services.ww.openWindow(
+                  win,
+                  "chrome://messenger/content/messengercompose/messengercompose.xhtml",
+                  "_blank",
+                  "chrome,dialog=no,all",
+                  args
                 );
-                args.appendElement(argstring);
-                args.appendElement(cmdLine);
-                getOrOpen3PaneWindow().then(win => {
-                  if (!MailServices.accounts.defaultAccount) {
-                    return; // No account yet; can't compose.
-                  }
-                  Services.ww.openWindow(
-                    win,
-                    "chrome://messenger/content/messengercompose/messengercompose.xhtml",
-                    "_blank",
-                    "chrome,dialog=no,all",
-                    args
-                  );
-                });
-                break;
-              }
-              default:
-                throw Components.Exception("", Cr.NS_ERROR_ABORT);
+              });
+              break;
             }
-            break;
-
-          default:
-            // Somebody sent us a remote command we don't know how to process:
-            // just abort.
-            throw Components.Exception(
-              `Unrecognized command: ${remoteParams[0]}`,
-              Cr.NS_ERROR_ABORT
-            );
-        }
+            default:
+              throw new Error(
+                `Unexpected xfedocommand param: ${remoteParams[0]}`
+              );
+          }
+          break;

-        cmdLine.preventDefault = true;
-      } catch (e) {
-        // If we had a -remote flag but failed to process it, throw
-        // NS_ERROR_ABORT so that the xremote code knows to return a failure
-        // back to the handling code.
-        dump(e);
-        throw Components.Exception("", Cr.NS_ERROR_ABORT);
+        default:
+          // Somebody sent us a remote command we don't know how to process:
+          // just abort.
+          throw Components.Exception(
+            `Unrecognized -remote command: ${remoteParams[0]}`,
+            Cr.NS_ERROR_ABORT
+          );
       }
+
+      cmdLine.preventDefault = true;
     }

     var chromeParam = cmdLine.handleFlagWithParam("chrome", false);
